113:                             int64_t &imageSize, Image2DType &imageMaskType,
114:                             Image2DType &imageVisualType ) const;
115: 
116:       /// @brief Reads an image
117:       /// @param [in] imageIndex index of the image. Must be less than GetImage2DCount()
