283:    int fd = ::open( fileName_.c_str(), flags, mode );
284:    if ( fd < 0 )
285:    {
286:       throw E57_EXCEPTION2( ErrorOpenFailed, "errno=" + toString( errno ) + " error='" +
287:                                                 strerror( errno ) + "' fileName=" + fileName +
288:                                                 " flags=" + toString( flags ) +
289:                                                 " mode=" + toString( mode ) );
